create table if not exists public.invitation_commissions (id uuid primary key default gen_random_uuid(),inviter_user_id uuid not null references auth.users(id) on delete restrict,registered_user_id uuid not null references auth.users(id) on delete restrict,invitation_code text not null,registration_id uuid,amount numeric(14,2) not null check (amount >= 0),currency text not null default 'ETB',status text not null default 'pending' check (status in ('pending','paid','cancelled')),transaction_reference text not null unique,eligibility_reason text,created_at timestamptz not null default now(),paid_at timestamptz,cancelled_at timestamptz,cancellation_reason text,constraint invitation_commissions_not_self check (inviter_user_id <> registered_user_id)); create unique index if not exists invitation_commissions_one_registration on public.invitation_commissions(registered_user_id) where status <> 'cancelled'; create index if not exists invitation_commissions_inviter_idx on public.invitation_commissions(inviter_user_id,created_at desc); create index if not exists invitation_commissions_status_idx on public.invitation_commissions(status,created_at desc); alter table public.invitation_commissions enable row level security; create or replace function public.cancel_invitation_commission(p_commission_id uuid,p_reason text) returns public.invitation_commissions language plpgsql security definer set search_path=public as $$ declare v_row public.invitation_commissions; begin if p_reason is null or length(trim(p_reason))<5 then raise exception 'Cancellation reason is required'; end if; update public.invitation_commissions set status='cancelled',cancelled_at=now(),cancellation_reason=left(trim(p_reason),500) where id=p_commission_id and status='pending' returning * into v_row; if v_row.id is null then raise exception 'Commission not found or no longer cancellable'; end if; return v_row; end; $$; revoke all on function public.cancel_invitation_commission(uuid,text) from public,anon,authenticated; create or replace function public.create_invitation_commission(p_inviter uuid,p_registered uuid,p_code text,p_registration uuid,p_amount numeric,p_currency text default 'ETB') returns public.invitation_commissions language plpgsql security definer set search_path=public as $$ declare v_row public.invitation_commissions; begin if p_inviter is null or p_registered is null or p_inviter=p_registered then raise exception 'Invalid invitation attribution'; end if; if p_code is null or length(trim(p_code))=0 then raise exception 'Invitation code is required'; end if; insert into public.invitation_commissions(inviter_user_id,registered_user_id,invitation_code,registration_id,amount,currency,transaction_reference,eligibility_reason) values(p_inviter,p_registered,trim(p_code),p_registration,greatest(coalesce(p_amount,0),0),coalesce(nullif(p_currency,''),'ETB'),'INV-'||upper(replace(gen_random_uuid()::text,'-','')),'Eligible registration invitation') on conflict (registered_user_id) where status <> 'cancelled' do nothing returning * into v_row; return v_row; end; $$; revoke all on function public.create_invitation_commission(uuid,uuid,text,uuid,numeric,text) from public,anon,authenticated;
